SELECT
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  st.store_key,
  st.store_id,
  st.store_name,
  st.region,
  st.store_format,
  p.category,
  p.subcategory,
  r.return_reason,
  r.is_restockable,
  COUNT(*) AS return_lines,
  SUM(CAST(r.return_quantity AS INT)) AS returned_units,
  SUM(r.refund_value) AS returns_value,
  SUM(r.restock_cost_credit) AS restock_cost_credit,
  SUM(CAST(r.has_receipt AS INT)) AS returns_with_receipt,
  SUM(CASE WHEN r.original_sales_line_id IS NULL THEN 0 ELSE 1 END) AS returns_linked_to_sales_line,
  SUM(CASE WHEN NOT r.original_sale_store_key IN (-1, r.store_key) THEN 1 ELSE 0 END) AS returned_at_other_store
FROM {{ ref('fact_returns') }} AS r
JOIN {{ ref('dim_date') }} AS d
  ON d.date_key = r.return_date_key
JOIN {{ ref('dim_retail_week') }} AS w
  ON w.retail_week_key = d.retail_week_key
JOIN {{ ref('dim_store') }} AS st
  ON st.store_key = r.store_key
JOIN {{ ref('dim_product') }} AS p
  ON p.product_key = r.product_key
GROUP BY
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  st.store_key,
  st.store_id,
  st.store_name,
  st.region,
  st.store_format,
  p.category,
  p.subcategory,
  r.return_reason,
